using ConRoi.Investigation.V36.R107;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (Application.dataPath != "C:/ConRoi_CheckoutTest/Assets")
                throw new Exception("Wrong project");
            var s = UnityEngine.Object.FindFirstObjectByType<InvestigationSession>();
            if (!s || !s.SavePath.Contains("Nav_fixed_20261108") || !File.Exists("Test/Output/NavFix_fixed_20261108/suite.txt"))
                throw new Exception("Wrong profile or unfinished suite");
            if (Enumerable.Range(0, SceneManager.sceneCount).Any(i => SceneManager.GetSceneAt(i).isDirty))
                throw new Exception("Dirty scene; no discard");
            File.WriteAllText("Test/Output/NavFix_fixed_20261108/pre-close-live.json", JsonUtility.ToJson(s.data, true));
            EditorApplication.isPlaying = false;
            double at = EditorApplication.timeSinceStartup;
            EditorApplication.CallbackFunction f = null;
            f = () =>
            {
                if (EditorApplication.isPlaying || EditorApplication.timeSinceStartup - at < 4)
                    return;
                EditorApplication.update -= f;
                if (Enumerable.Range(0, SceneManager.sceneCount).Any(i => SceneManager.GetSceneAt(i).isDirty))
                    throw new Exception("Dirty Edit state; do not close");
                File.WriteAllText("Test/Output/NavFix_fixed_20261108/close.txt", "Preserved state before Play stop; Edit clean; Editor exit without scene save.");
                EditorApplication.Exit(0);
            };
            EditorApplication.update += f;
            r.Log("Controlled close after preserved reproduction state");
        }
    }
}

